// This file was generated by Prisma and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// `prisma generate` does not connect to the database, but the config still
// needs a syntactically valid URL. Use a placeholder so builds and CI can
// generate the client without a real DATABASE_URL; migrate/db push override it
// through the real environment.
const databaseUrl =
  process.env.DATABASE_URL ?? "mysql://placeholder:placeholder@localhost:3306/placeholder";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: databaseUrl,
  },
});
